import React from 'react';

const Header = () => {
  return (
    <header className="bg-brand-green text-white shadow-md">
      <div className="container mx-auto flex justify-between items-center p-4">
        <div>
          <h1 className="text-2xl font-bold">Dietitian Pradeepa's Clinic</h1>
          <p>பரிபூரண ஆரோக்கியத்துடன் வாழ்க!</p>
        </div>
        <nav className="hidden md:flex space-x-8">
          <a href="#home" className="font-semibold hover:text-gray-200 transition-colors">Home</a>
          <a href="#about" className="font-semibold hover:text-gray-200 transition-colors">About Us</a>
          <a href="#services" className="font-semibold hover:text-gray-200 transition-colors">Services</a>
          <a href="#contact" className="font-semibold hover:text-gray-200 transition-colors">Contact Us</a>
        </nav>
      </div>
    </header>
  );
};

export default Header;
